 void UpdateControlVisuals(){int keyMask=keyboardMode&&IsActive?KeyboardInput.Read(store.Value.Players[player]):0;int[] values=keyboardMode?Enumerable.Range(0,10).Select(i=>(keyMask&(1<<i))!=0?1:0).ToArray():SelectedPad() is PadState p&&Profile() is PadProfile c?PadLogic.Read(p,c):new int[10];foreach(var kv in diagramButtons){kv.Value.Background=Brush(values[kv.Key]!=0?"#6B5621":"#19191F");kv.Value.BorderBrush=Brush(capture==kv.Key?"#F2C75C":values[kv.Key]!=0?"#F2C75C":"#36363F");}}
 void BeginCapture(int action,bool keyboard){CancelCapture();if(!keyboard&&SelectedPad()==null)return;capture=action;captureKey=keyboard;armed=keyboard;captureStart=DateTime.UtcNow;lastPad=SelectedPad();captureNote!.Text=L.F(keyboard?"Pulsa una tecla para {0}. Esc cancela.":"Suelta el mando y pulsa una entrada para {0}. Esc cancela.",L.T(Defaults.Actions[action]));}
 void CancelCapture(){capture=-1;armed=false;lastPad=null;}
 void RefreshBindingLabels(){var p=SelectedPad();var c=Profile();for(int i=0;i<bindingButtons.Count;i++)bindingButtons[i].Content=PadLogic.Label(c?.Bindings[i],p,c?.Family??"Auto");foreach(var item in diagramButtons)if(!keyboardMode&&item.Key>=4&&item.Key<8)item.Value.Content=PadLogic.Label(c?.Bindings[item.Key],p,c?.Family??"Auto");}
 void NavigateWithPad(){
  var pad=SelectedPad()??pads.FirstOrDefault();if(pad==null){menuMask=0;return;}var profile=store.Value.Pads.GetValueOrDefault(pad.Key)??PadLogic.Default(pad);var v=PadLogic.Read(pad,profile);int mask=0;for(int i=0;i<10;i++)if(v[i]!=0)mask|=1<<i;
  var now=Environment.TickCount64;int edge=mask&~menuMask;int direction=mask&15;if(direction!=0&&now>=menuRepeat){edge|=direction;menuRepeat=now+180;}if(direction==0)menuRepeat=now+300;menuMask=mask;
  if((edge&32)!=0){if(page!="Inicio"){Navigate("Inicio");play?.Focus();}return;}
  var focused=Keyboard.FocusedElement as UIElement;
  if(focused is Slider slider&&(edge&12)!=0){slider.Value=Math.Clamp(slider.Value+((edge&8)!=0?1:-1)*slider.SmallChange,slider.Minimum,slider.Maximum);return;}
  if(focused is ComboBox combo&&((edge&12)!=0||(combo.IsDropDownOpen&&(edge&3)!=0))){combo.SelectedIndex=Math.Clamp(combo.SelectedIndex+((edge&10)!=0?1:-1),0,combo.Items.Count-1);return;}
  if((edge&1)!=0)focused?.MoveFocus(new TraversalRequest(FocusNavigationDirection.Previous));if((edge&2)!=0)focused?.MoveFocus(new TraversalRequest(FocusNavigationDirection.Next));
  if((edge&16)!=0){if(focused is Button b&&b.IsEnabled)b.RaiseEvent(new RoutedEventArgs(ButtonBase.ClickEvent));else if(focused is ToggleButton toggle&&toggle.IsEnabled)toggle.IsChecked=toggle is RadioButton?true:toggle.IsChecked!=true;else if(focused is ComboBox select)select.IsDropDownOpen=!select.IsDropDownOpen;}
 }
